"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[411],{3437(t){t.exports=JSON.parse('{"tag":{"label":"Induction","permalink":"/concepts/tags/induction","allTagsPath":"/concepts/tags","count":1,"items":[{"id":"mathematical-background/induction-and-recurrences","title":"Induction, Correctness and Recurrences","description":"Recursive algorithms raise two questions: is the algorithm correct, and how long does it take? The answer to both uses the same idea. A recursive algorithm solves a problem by trusting that the smaller calls work; mathematical induction is the tool that makes that trust rigorous, and a recurrence is the equation that describes its cost in terms of the cost of the smaller calls.","permalink":"/concepts/mathematical-background/induction-and-recurrences"}],"unlisted":false}}')}}]);